select case when credit_limit >= 17900 then 'high' when credit_limit >= 6700 then 'mid' else 'low' end as credit_limit_bucket, sum(age) as total_age, count(*) as cnt, sum(sum(age)) over (order by case when credit_limit >= 17900 then 'high' when credit_limit >= 6700 then 'mid' else 'low' end) as cumulative_age from customers group by case when credit_limit >= 17900 then 'high' when credit_limit >= 6700 then 'mid' else 'low' end
